// The restart/idempotency probes (recommendation-sorting task 2.3): the
// design's restart-survivability contract (unstamped rows re-derive,
// stamped rows never double-count, the watched PK dedupes rewatches,
// no-duration never completes) driven over the LANDED machinery — the real
// detector, the real janitor sweep, the real store — never a reimplementation.

// recsProbeFixture opens the FIRST store of a restart probe at a
// caller-retained sqlite path, with its seeded module registry. The path
// comes back so recsReopen can stand in for the process restart.
func recsProbeFixture(t *testing.T) (*store.Store, *module.Registry, context.Context, string) {
	t.Helper()
	dbPath := filepath.Join(t.TempDir(), "recs_probe.db")
	st, reg, ctx := openRecsProbeStore(t, dbPath)
	return st, reg, ctx, dbPath
}

// recsReopen simulates the restart: a NEW Store instance (plus its registry)
// over the SAME sqlite file. The caller closes the previous instance first —
// the honest restart shape, not two live handles.
func recsReopen(t *testing.T, dbPath string) (*store.Store, *module.Registry) {
	t.Helper()
	st, reg, _ := openRecsProbeStore(t, dbPath)
	return st, reg
}

// openRecsProbeStore opens one real store at dbPath with the seeded module
// registry (the recsJanitorFixture posture).
func openRecsProbeStore(t *testing.T, dbPath string) (*store.Store, *module.Registry, context.Context) {
	t.Helper()
	ctx := context.Background()
	st, err := store.Open(ctx, dbPath)
	if err != nil {
		t.Fatalf("store.Open %s: %v", dbPath, err)
	}
	t.Cleanup(func() { _ = st.Close() })
	reg, err := module.Open(ctx, st)
	if err != nil {
		t.Fatalf("module.Open: %v", err)
	}
	return st, reg, ctx
}

// putRecsProbeItem persists one tv item whose document carries BOTH the
// ffprobe fragment (the detector's completion gate) and the tv-parser
// namespace under "sources" (the janitor's tag carrier — ResolveGenres reads
// doc["sources"][pluginID]) — a doc shape the probe joints need and the
// existing per-file helpers each only cover half of.
func putRecsProbeItem(t *testing.T, ctx context.Context, st *store.Store, id string, libraryID int64, ffprobe, tvparser string) {
	t.Helper()
	doc := `{"ffprobe": ` + ffprobe + `, "sources": {"tv-parser": ` + tvparser + `}}`
	if err := st.PutItem(ctx, store.Item{
		ID: id, ModuleID: "tv", LibraryID: libraryID, FileID: "f_" + id,
		Document: []byte(doc),
	}); err != nil {
		t.Fatalf("PutItem %s: %v", id, err)
	}
}

// TestRecsUnstampedResume: a completion lands but the janitor never runs
// before the process dies — the watched row sits UNSTAMPED (applied_at NULL).
// A fresh boot (a new Store over the same sqlite file) finds the row in its
// queue and its first sweep consumes it: weights applied, row stamped.
func TestRecsUnstampedResume(t *testing.T) {
	st, _, ctx, dbPath := recsProbeFixture(t)

	putRecsProbeItem(t, ctx, st, "it_resume", 2,
		`{"format": {"duration": "3600"}}`,
		`{"description": "d", "genres": ["Action", "Comedy"]}`)
	newWatchDetect(st)(ctx, "it_resume", 3300, false) // 91.7% — completion recorded, NO sweep ran
	if got := watchedCount(t, ctx, st); got != 1 {
		t.Fatalf("unstamped watched rows before restart = %d, want 1", got)
	}
	drainRecsWake(t) // the poke dies with the process; never consumed

	// RESTART: the previous instance closes; a new Store opens over the file.
	if err := st.Close(); err != nil {
		t.Fatalf("close before restart: %v", err)
	}
	st2, reg2 := recsReopen(t, dbPath)

	// The unstamped row SURVIVED the restart — still in the learning queue.
	if got := watchedCount(t, ctx, st2); got != 1 {
		t.Fatalf("unstamped watched rows after restart = %d, want 1 (restart must not lose the queue)", got)
	}

	// The fresh boot's first janitor pass consumes it exactly once.
	newRecsSweep(st2, reg2)(ctx)
	recsAssertWeights(t, st2, map[string]int64{"action": 1, "comedy": 1})
	recsAssertQueueEmpty(t, st2)
}

// TestRecsStampedSkip: a row the first boot's pass already stamped is
// skipped by a fresh boot's sweep — the stamp survives the restart, the
// fresh boot's queue read is already empty for it, and a sweep over a boot
// that ALSO carries a new unstamped row consumes ONLY the new row (no
// double-count of the stamped one).
func TestRecsStampedSkip(t *testing.T) {
	st, reg, ctx, dbPath := recsProbeFixture(t)

	putRecsProbeItem(t, ctx, st, "it_stamped", 1, `{}`,
		`{"description": "d", "genres": ["Action"]}`)
	if err := st.InsertWatched(ctx, "it_stamped", 1, "", time.Now(), access.System()); err != nil {
		t.Fatalf("InsertWatched stamped: %v", err)
	}
	newRecsSweep(st, reg)(ctx) // first boot learns + stamps
	recsAssertWeights(t, st, map[string]int64{"action": 1})
	recsAssertQueueEmpty(t, st)

	if err := st.Close(); err != nil {
		t.Fatalf("close before restart: %v", err)
	}
	st2, reg2 := recsReopen(t, dbPath)

	// The stamp survived: the fresh boot's queue read is empty for the row.
	if got := watchedCount(t, ctx, st2); got != 0 {
		t.Fatalf("stamped row re-entered the queue after restart = %d rows, want 0", got)
	}
	// A NEW completion lands on the fresh boot; the sweep must consume only
	// it — the stamped row's tags must NOT increment again.
	putRecsProbeItem(t, ctx, st2, "it_fresh", 1, `{}`,
		`{"description": "d", "genres": ["Comedy"]}`)
	if err := st2.InsertWatched(ctx, "it_fresh", 1, "", time.Now(), access.System()); err != nil {
		t.Fatalf("InsertWatched fresh: %v", err)
	}
	newRecsSweep(st2, reg2)(ctx)
	recsAssertWeights(t, st2, map[string]int64{"action": 1, "comedy": 1})
	recsAssertQueueEmpty(t, st2)
}

// TestRecsRewatchNoop: the same item watched again POST-completion is a
// no-op end-to-end — the watched PK folds the repeat insert (nothing new
// lands) and a sweep over it adds no weights.
func TestRecsRewatchNoop(t *testing.T) {
	st, reg, ctx, _ := recsProbeFixture(t)

	putRecsProbeItem(t, ctx, st, "it_rewatch", 1,
		`{"format": {"duration": "600"}}`,
		`{"description": "d", "genres": ["Action"]}`)
	detect := newWatchDetect(st)
	detect(ctx, "it_rewatch", 570, false) // 95% — first completion
	drainRecsWake(t)
	newRecsSweep(st, reg)(ctx)
	recsAssertWeights(t, st, map[string]int64{"action": 1})
	recsAssertQueueEmpty(t, st)

	// The rewatch: past the floor again, long after the first completion.
	detect(ctx, "it_rewatch", 599, false)
	drainRecsWake(t)
	if got := watchedCount(t, ctx, st); got != 0 {
		t.Fatalf("rewatch landed %d unstamped rows, want 0 (PK dedupes)", got)
	}

	// The sweep over the rewatch is a no-op — no weights added.
	newRecsSweep(st, reg)(ctx)
	recsAssertWeights(t, st, map[string]int64{"action": 1})
	recsAssertQueueEmpty(t, st)
}

// TestRecsNoDurationNeverCompletes: a progress write for an item with NO
// stored ffprobe duration never lands a watched row — even at an absurd
// position, even though the item's document would carry tags if it ever
// completed — and the janitor sweep over that honest absence is a no-op
// end-to-end (no rows, no weights, no poke).
func TestRecsNoDurationNeverCompletes(t *testing.T) {
	st, reg, ctx, _ := recsProbeFixture(t)

	// No ffprobe fragment at all; the tv-parser namespace WOULD carry tags.
	putRecsProbeItem(t, ctx, st, "it_nodur", 1, `{}`,
		`{"description": "d", "genres": ["Action"]}`)

	newWatchDetect(st)(ctx, "it_nodur", 999999, false) // no duration to compare against

	if got := watchedCount(t, ctx, st); got != 0 {
		t.Fatalf("watched rows = %d, want 0 without a stored duration", got)
	}
	if drainRecsWake(t) {
		t.Fatal("recs wake poked without a completion insert")
	}

	// The sweep over the honest absence is a no-op: nothing to learn, no
	// fabricated weights.
	newRecsSweep(st, reg)(ctx)
	recsAssertWeights(t, st, map[string]int64{})
	recsAssertQueueEmpty(t, st)
}
